// Class with TypeScript
class EventEmitter<T> {
  private listeners = new Map<string, ((data: T) => void)[]>();

  on(event: string, cb: (data: T) => void): this {
    const cbs = this.listeners.get(event) ?? [];
    this.listeners.set(event, [...cbs, cb]);
    return this; // fluent interface
  }

  emit(event: string, data: T): void {
    this.listeners.get(event)?.forEach(cb => cb(data));
  }
}

// Inheritance
class Logger extends EventEmitter<string> {
  constructor(private prefix: string) { super(); }

  log(msg: string): void {
    const entry = `[${this.prefix}] ${msg}`;
    console.log(entry);
    this.emit('log', entry);
  }
}

